head.script:
scwin.tData = {
    "description" : "[multiselect > E > onviewchange]<br/>MultiSelect 컴포넌트에서 사용자의 조작에 의해 아이템 선택이 변경되면 발생합니다.",
    "validation" : [
        "사용자의 조작에 의해 기존과 동일한 아이템을 선택한 경우엔 onviewchange 이벤트가 발생하지 않고 onchange 이벤트만 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onviewchange =====");
};



// onchange 동시 부착 (동일 아이템 재선택 시 onchange 만 발생 검증)
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onchange =====");
};



scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onviewchange", "onchange"]);

    await $c.gcm.createBasicMultiSelect('', eList);
}
